import http.server, json, sys, os
from urllib.parse import urlparse, parse_qs

class Handler(http.server.BaseHTTPRequestHandler):
    def log_message(self, format, *args):
        pass
    def do_any(self):
        parsed = urlparse(self.path)
        length = int(self.headers.get('Content-Length', 0))
        body = self.rfile.read(length).decode('utf-8', errors='replace') if length else ''
        # collect
        print(f"=== {self.command} {self.path} ===", flush=True)
        print(f"Headers: {dict(self.headers)}", flush=True)
        print(f"Body: {body}", flush=True)
        # respond simple json
        resp = {"method": self.command, "path": self.path, "headers": dict(self.headers), "body": body, "query": parsed.query}
        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.send_header("X-Custom-Resp", "testvalue")
        self.end_headers()
        self.wfile.write(json.dumps(resp).encode())
    def do_GET(self): self.do_any()
    def do_POST(self): self.do_any()
    def do_PUT(self): self.do_any()
    def do_DELETE(self): self.do_any()
    def do_PATCH(self): self.do_any()
    def do_OPTIONS(self): self.do_any()
    def do_HEAD(self): self.do_any()

http.server.HTTPServer(('127.0.0.1', 8765), Handler).serve_forever()
