func methodOrDefault(method string, items []string, bodyRaw string) string {
	if method != "" {
		return method
	}
	// if data or bodyRaw or file, POST else GET
	hasData := false
	for _, it := range items {
		if strings.Contains(it, "=") && !strings.Contains(it, "==") {
			hasData = true
			break
		}
		if strings.Contains(it, "@") {
			hasData = true
			break
		}
	}
	if bodyRaw != "" {
		hasData = true
	}
	if hasData {
		return "POST"
	}
	return "GET"
}

func buildClient() *http.Client {
	// proxy
	var proxyFunc func(*http.Request) (*url.URL, error)
	if *proxy != "" {
		proxyURL, err := url.Parse(*proxy)
		if err == nil {
			proxyFunc = http.ProxyURL(proxyURL)
		}
	}
	transport := &http.Transport{
		Proxy: proxyFunc,
		TLSClientConfig: &tls.Config{
			InsecureSkipVerify: *insecure || *insecureShort,
		},
	}
	return &http.Client{
		Transport: transport,
	}
}

