					if barLen == 0 && cnt > 0 {
						barLen = 1
					}
					bar = strings.Repeat("∎", barLen)
				}
				fmt.Printf("  %.3f [%d]\t|%s\n", tval, cnt, bar)
			}
		}
		fmt.Printf("\nLatency distribution:\n")
		sorted := make([]time.Duration, len(times))
		copy(sorted, times)
		sort.Slice(sorted, func(i, j int) bool { return sorted[i] < sorted[j] })
		if len(sorted) > 0 {
			percs := []int{10, 25, 50, 75, 90}
			for _, p := range percs {
				idx := int(float64(p) / 100 * float64(len(sorted)))
				if idx >= len(sorted) {
					idx = len(sorted) - 1
				}
				fmt.Printf("  %d%% in %.4f secs.\n", p, sorted[idx].Seconds())
			}
		}
