		dataItems   = []dataItem{}
		queryParams = []dataItem{}
		fileUploads = []struct{ key, path string }{}
	)
	for _, it := range items {
		if strings.Contains(it, "@") {
			parts := strings.SplitN(it, "@", 2)
			if len(parts) == 2 {
				fileUploads = append(fileUploads, struct{ key, path string }{parts[0], parts[1]})
				continue
			}
		}
		if strings.Contains(it, ":") {
			colonIdx := strings.Index(it, ":")
			eqIdx := strings.Index(it, "=")
			if eqIdx == -1 || colonIdx < eqIdx {
				parts := strings.SplitN(it, ":", 2)
				k := strings.TrimSpace(parts[0])
				v := strings.TrimSpace(parts[1])
				headers[k] = v
				continue
			}
		}
		if strings.Contains(it, "=") {
			isQuery := strings.Contains(it, "==")
			parts := strings.SplitN(it, "=", 2)
			k := parts[0]
			v := parts[1]
			di := dataItem{key: k, value: v, isQuery: isQuery}
