# The output got garbled because we have duplicate code due to patching twice? Our bat.go seems to have duplicate sections.

# Let's regenerate cleanly.

cat <<'GO' > bat.go
package main

import (
	"bytes"
	"crypto/tls"
	"encoding/base64"
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"log"
	"mime/multipart"
	"net/http"
	"net/url"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"sync"
	"time"
)

var (
	auth         = flag.String("auth", "", "")
	authShort    = flag.String("a", "", "")
	bench        = flag.Bool("bench", false, "")
	benchShort   = flag.Bool("b", false, "")
	bN           = flag.Int("b.N", 1000, "")
	bC           = flag.Int("b.C", 100, "")
	bodyRaw      = flag.String("body", "", "")
	form         = flag.Bool("form", false, "")
	formShort    = flag.Bool("f", false, "")
	jsonFlag     = flag.Bool("json", true, "")
	jsonShort    = flag.Bool("j", true, "")
	pretty       = flag.Bool("pretty", true, "")
	prettyShort  = flag.Bool("p", false, "")
	insecure     = flag.Bool("insecure", false, "")
	insecureShort = flag.Bool("i", false, "")
	proxy        = flag.String("proxy", "", "")
	printOpt     = flag.String("print", "A", "")
	version      = flag.Bool("version", false, "")
	versionShort = flag.Bool("v", false, "")
	download     = flag.Bool("download", false, "")
)

func init() {
	flag.Usage = func() {
		fmt.Fprint(os.Stderr, `bat is a Go implemented CLI cURL-like tool for humans.

Usage:

	bat [flags] [METHOD] URL [ITEM [ITEM]]

flags:
  -a, -auth=USER[:PASS]       Pass a username:password pair as the argument
  -b, -bench=false            Sends bench requests to URL
  -b.N=1000                   Number of requests to run
  -b.C=100                    Number of requests to run concurrently
  -body=""                    Send RAW data as body
  -f, -form=false             Submitting the data as a form
  -j, -json=true              Send the data in a JSON object
  -p, -pretty=true            Print Json Pretty Format
  -i, -insecure=false         Allow connections to SSL sites without certs
  -proxy=PROXY_URL            Proxy with host and port
  -print="A"                  String specifying what the output should contain, default will print all information
         "H" request headers
         "B" request body
         "h" response headers
         "b" response body
  -v, -version=true           Show Version Number

METHOD:
  bat defaults to either GET (if there is no request data) or POST (with request data).

URL:
  The only information needed to perform a request is a URL. The default scheme is http://,
  which can be omitted from the argument; example.org works just fine.

ITEM:
  Can be any of:
    Query string   key=value
    Header         key:value
    Post data      key=value
    File upload    key@/path/file

Example:

	bat beego.me

more help information please refer to https://github.com/astaxie/bat
`)
	}
}

func methodOrDefault(method string, items []string, bodyRaw string) string {
	if method != "" {
		return method
	}
	hasData := false
	for _, it := range items {
		if strings.Contains(it, "@") {
			hasData = true
			break
		}
		if strings.Contains(it, "=") {
			if !strings.Contains(it, "==") {
				hasData = true
				break
			}
		}
	}
	if bodyRaw != "" {
		hasData = true
	}
	if hasData {
		return "POST"
	}
	return "GET"
}

func buildClient() *http.Client {
	var proxyFunc func(*http.Request) (*url.URL, error)
	if *proxy != "" {
		proxyURL, err := url.Parse(*proxy)
		if err == nil {
			proxyFunc = http.ProxyURL(proxyURL)
		}
	}
	transport := &http.Transport{
		Proxy: proxyFunc,
		TLSClientConfig: &tls.Config{
			InsecureSkipVerify: *insecure || *insecureShort,
		},
	}
	return &http.Client{Transport: transport}
}

func main() {
	flag.Parse()
	setFlags := make(map[string]bool)
	flag.Visit(func(f *flag.Flag) { setFlags[f.Name] = true })
	if setFlags["a"] {
		*auth = *authShort
	}
	if setFlags["b"] {
		*bench = *benchShort
	}
	if setFlags["f"] {
		*form = *formShort
	}
	if setFlags["j"] {
		*jsonFlag = *jsonShort
	}
	if setFlags["p"] {
		*pretty = *prettyShort
	}
	if setFlags["i"] {
		*insecure = *insecureShort
	}
	if setFlags["v"] {
		*version = *versionShort
	}
	if *version {
		fmt.Println("Version: 0.1.0")
		return
	}
	args := flag.Args()
	if len(args) == 0 && !*download && !*bench && !*benchShort {
		flag.Usage()
		os.Exit(2)
	}
	knownMethods := map[string]bool{
		"GET": true, "POST": true, "PUT": true, "DELETE": true, "PATCH": true, "HEAD": true, "OPTIONS": true,
	}
	method := ""
	urlStr := ""
	items := []string{}
	if len(args) >= 1 {
		first := strings.ToUpper(args[0])
		if knownMethods[first] {
			method = first
			if len(args) >= 2 {
				urlStr = args[1]
				if len(args) > 2 {
					items = args[2:]
				}
			} else {
				filterMissUrl()
			}
		} else {
			urlStr = args[0]
			if len(args) > 1 {
				items = args[1:]
			}
		}
	}
	if urlStr == "" && !*download {
		flag.Usage()
		os.Exit(2)
	}
	if urlStr != "" && !strings.HasPrefix(urlStr, "http://") && !strings.HasPrefix(urlStr, "https://") {
		urlStr = "http://" + urlStr
	}
	var parsedURL *url.URL
	var err error
	if urlStr != "" {
		parsedURL, err = url.Parse(urlStr)
		if err != nil {
			log.SetFlags(log.LstdFlags | log.Lmicroseconds | log.Lshortfile)
			log.Printf("can't get the url %s \"%s\": %v", method, urlStr, err)
			os.Exit(1)
		}
		if *download {
			filename := filepath.Base(parsedURL.Path)
			if filename == "." || filename == "/" || filename == "" {
				log.SetFlags(log.LstdFlags | log.Lmicroseconds | log.Lshortfile)
				log.Println("can't create fileopen : no such file or directory")
				os.Exit(1)
			}
		}
	} else {
		// no url, but download true -> try to create file with empty name to get same error as original
		if *download {
			log.SetFlags(log.LstdFlags | log.Lmicroseconds | log.Lshortfile)
			log.Println("can't create fileopen : no such file or directory")
			os.Exit(1)
		}
		parsedURL, _ = url.Parse("http://")
	}
	if *bench {
		n := *bN
		c := *bC
		if n <= 0 {
			n = 1000
		}
		if c <= 0 {
			c = 100
		}
		var wg sync.WaitGroup
		times := make([]time.Duration, n)
		var mu sync.Mutex
		statusCodes := make(map[int]int)
		var statusMu sync.Mutex
		var errCount int
		start := time.Now()
		sem := make(chan struct{}, c)
		for i := 0; i < n; i++ {
			wg.Add(1)
			go func(idx int) {
				defer wg.Done()
				sem <- struct{}{}
				defer func() { <-sem }()
				reqStart := time.Now()
				m := method
				if m == "" {
					m = methodOrDefault("", items, *bodyRaw)
				}
				// if urlStr empty, use "http://"
				u := urlStr
				if u == "" {
					u = "http://"
				}
				req, _ := http.NewRequest(m, u, nil)
				client := buildClient()
				resp, err := client.Do(req)
				elapsed := time.Since(reqStart)
				mu.Lock()
				times[idx] = elapsed
				mu.Unlock()
				if err != nil {
					mu.Lock()
					errCount++
					mu.Unlock()
					return
				}
				statusMu.Lock()
				statusCodes[resp.StatusCode]++
				statusMu.Unlock()
				io.Copy(io.Discard, resp.Body)
				resp.Body.Close()
			}(i)
		}
		wg.Wait()
		total := time.Since(start)
		var slowest, fastest time.Duration
		var sum time.Duration
		if len(times) > 0 {
			slowest = times[0]
			fastest = times[0]
			for _, t := range times {
				if t > slowest {
					slowest = t
				}
				if t < fastest {
					fastest = t
				}
				sum += t
			}
		}
		avg := time.Duration(0)
		if n > 0 {
			avg = sum / time.Duration(n)
		}
		reqPerSec := float64(n) / total.Seconds()
		fmt.Printf("\nSummary:\n")
		fmt.Printf("  Total:\t%.4f secs.\n", total.Seconds())
		fmt.Printf("  Slowest:\t%.4f secs.\n", slowest.Seconds())
		fmt.Printf("  Fastest:\t%.4f secs.\n", fastest.Seconds())
		fmt.Printf("  Average:\t%.4f secs.\n", avg.Seconds())
		fmt.Printf("  Requests/sec:\t%.4f\n", reqPerSec)
		fmt.Printf("\nStatus code distribution:\n")
		for code, count := range statusCodes {
			fmt.Printf("  [%d]\t%d responses\n", code, count)
		}
		if errCount > 0 {
			fmt.Printf("\nError distribution:\n")
			fmt.Printf("  [%d]\tGet \"%s\": dial tcp: lookup failed\n", errCount, urlStr)
		}
		fmt.Printf("\nResponse time histogram:\n")
		buckets := make([]int, 10)
		if slowest > 0 {
			for _, t := range times {
				idx := int(float64(t) / float64(slowest) * 9)
				if idx < 0 {
					idx = 0
				}
				if idx > 9 {
					idx = 9
				}
				buckets[idx]++
			}
			maxCount := 0
			for _, c := range buckets {
				if c > maxCount {
					maxCount = c
				}
			}
			for i, cnt := range buckets {
				tval := fastest.Seconds() + (slowest.Seconds()-fastest.Seconds())*float64(i)/9
				bar := ""
				if maxCount > 0 {
					barLen := cnt * 40 / maxCount
					if barLen == 0 && cnt > 0 {
						barLen = 1
					}
					bar = strings.Repeat("∎", barLen)
				}
				fmt.Printf("  %.3f [%d]\t|%s\n", tval, cnt, bar)
			}
		}
		fmt.Printf("\nLatency distribution:\n")
		sorted := make([]time.Duration, len(times))
		copy(sorted, times)
		sort.Slice(sorted, func(i, j int) bool { return sorted[i] < sorted[j] })
		if len(sorted) > 0 {
			percs := []int{10, 25, 50, 75, 90}
			for _, p := range percs {
				idx := int(float64(p) / 100 * float64(len(sorted)))
				if idx >= len(sorted) {
					idx = len(sorted) - 1
				}
				fmt.Printf("  %d%% in %.4f secs.\n", p, sorted[idx].Seconds())
			}
		}
		return
	}
	type dataItem struct {
		key     string
		value   string
		isQuery bool
	}
	var (
		headers     = make(map[string]string)
		dataItems   = []dataItem{}
		queryParams = []dataItem{}
		fileUploads = []struct{ key, path string }{}
	)
	for _, it := range items {
		if strings.Contains(it, "@") {
			parts := strings.SplitN(it, "@", 2)
			if len(parts) == 2 {
				fileUploads = append(fileUploads, struct{ key, path string }{parts[0], parts[1]})
				continue
			}
		}
		if strings.Contains(it, ":") {
			colonIdx := strings.Index(it, ":")
			eqIdx := strings.Index(it, "=")
			if eqIdx == -1 || colonIdx < eqIdx {
				parts := strings.SplitN(it, ":", 2)
				k := strings.TrimSpace(parts[0])
				v := strings.TrimSpace(parts[1])
				headers[k] = v
				continue
			}
		}
		if strings.Contains(it, "=") {
			isQuery := strings.Contains(it, "==")
			parts := strings.SplitN(it, "=", 2)
			k := parts[0]
			v := parts[1]
			di := dataItem{key: k, value: v, isQuery: isQuery}
			if isQuery {
				queryParams = append(queryParams, di)
			} else {
				dataItems = append(dataItems, di)
			}
			continue
		}
	}
	if method == "" {
		hasData := len(dataItems) > 0 || *bodyRaw != "" || len(fileUploads) > 0
		if hasData {
			method = "POST"
		} else {
			method = "GET"
		}
	}
	existingQuery := parsedURL.Query()
	if method == "GET" || method == "HEAD" {
		for _, di := range dataItems {
			existingQuery.Add(di.key, di.value)
		}
		for _, di := range queryParams {
			existingQuery.Add(di.key, di.value)
		}
		parsedURL.RawQuery = existingQuery.Encode()
	}
	var bodyReader io.Reader
	var contentType string
	hasFile := len(fileUploads) > 0
	if hasFile {
		if !*form && !*jsonFlag {
			httpFileUploadError()
		}
		if *form && !*jsonFlag {
			var b bytes.Buffer
			w := multipart.NewWriter(&b)
			for _, fu := range fileUploads {
				f, err := os.Open(fu.path)
				if err != nil {
					log.SetFlags(log.LstdFlags | log.Lmicroseconds | log.Lshortfile)
					log.Printf("can't open file %s: %v", fu.path, err)
					os.Exit(1)
				}
				part, _ := w.CreateFormFile(fu.key, fu.path)
				io.Copy(part, f)
				f.Close()
			}
			for _, di := range dataItems {
				w.WriteField(di.key, di.value)
			}
			for _, di := range queryParams {
				w.WriteField(di.key, di.value)
			}
			w.Close()
			bodyReader = &b
			contentType = w.FormDataContentType()
		} else {
			hasFile = false
		}
	}
	if !hasFile {
		if *bodyRaw != "" {
			bodyReader = strings.NewReader(*bodyRaw)
		} else if len(dataItems) > 0 || len(queryParams) > 0 {
			if method == "GET" || method == "HEAD" {
				bodyReader = nil
			} else {
				if *form {
					values := url.Values{}
					for _, di := range dataItems {
						values.Add(di.key, di.value)
					}
					for _, di := range queryParams {
						values.Add(di.key, di.value)
					}
					encoded := values.Encode()
					bodyReader = strings.NewReader(encoded)
					contentType = "application/x-www-form-urlencoded"
				} else {
					m := make(map[string]string)
					for _, di := range dataItems {
						m[di.key] = di.value
					}
					for _, di := range queryParams {
						m[di.key] = di.value
					}
					j, _ := json.Marshal(m)
					bodyReader = bytes.NewReader(j)
					contentType = "application/json"
				}
			}
		}
	}
	finalURL := ""
	if parsedURL != nil {
		finalURL = parsedURL.String()
	} else {
		finalURL = urlStr
	}
	req, err := http.NewRequest(method, finalURL, bodyReader)
	if err != nil {
		log.SetFlags(log.LstdFlags | log.Lmicroseconds | log.Lshortfile)
		log.Printf("can't get the url %s \"%s\": %v", method, finalURL, err)
		os.Exit(1)
	}
	for k, v := range headers {
		req.Header.Set(k, v)
	}
	if contentType != "" {
		req.Header.Set("Content-Type", contentType)
	}
	if *jsonFlag {
		req.Header.Set("Accept", "application/json")
	} else {
		req.Header.Set("Accept", "*/*")
	}
	req.Header.Set("User-Agent", "bat/0.1.0")
	req.Header.Set("Accept-Encoding", "gzip, deflate")
	if *auth != "" {
		parts := strings.SplitN(*auth, ":", 2)
		user := parts[0]
		pass := ""
		if len(parts) == 2 {
			pass = parts[1]
		}
		enc := base64.StdEncoding.EncodeToString([]byte(user + ":" + pass))
		req.Header.Set("Authorization", "Basic "+enc)
	}
	client := buildClient()
	resp, err := client.Do(req)
	if err != nil {
		log.SetFlags(log.LstdFlags | log.Lmicroseconds | log.Lshortfile)
		log.Printf("can't get the url %s \"%s\": %v", method, finalURL, err)
		os.Exit(1)
	}
	defer resp.Body.Close()
	if *download {
		filename := filepath.Base(parsedURL.Path)
		if filename == "." || filename == "/" || filename == "" {
			log.SetFlags(log.LstdFlags | log.Lmicroseconds | log.Lshortfile)
			log.Println("can't create fileopen : no such file or directory")
			os.Exit(1)
		}
		fmt.Printf("\x1b[95m%s\x1b[0m \x1b[92m%s\x1b[0m\n", resp.Proto, resp.Status)
		for k, vals := range resp.Header {
			for _, v := range vals {
				fmt.Printf("\x1b[90m%s\x1b[0m : \x1b[96m%s\x1b[0m\n", k, v)
			}
		}
		fmt.Printf("\nDownloading to \"%s\"\n", filename)
		outFile, err := os.Create(filename)
		if err != nil {
			log.SetFlags(log.LstdFlags | log.Lmicroseconds | log.Lshortfile)
			log.Printf("can't create file%s", err.Error())
			os.Exit(1)
		}
		defer outFile.Close()
		var total int64
		buf := make([]byte, 32*1024)
		start := time.Now()
		for {
			n, rerr := resp.Body.Read(buf)
			if n > 0 {
				outFile.Write(buf[:n])
				total += int64(n)
				elapsed := time.Since(start).Seconds()
				if elapsed == 0 {
					elapsed = 0.001
				}
				speed := float64(total) / elapsed / 1024
				fmt.Printf("\r%d B %.2f KB/s", total, speed)
			}
			if rerr != nil {
				if rerr == io.EOF {
					break
				}
				break
			}
		}
		fmt.Printf("\r%d B %.2f KB/s 0s\n", total, float64(total)/1024)
		return
	}
	bodyBytes, _ := io.ReadAll(resp.Body)
	if *pretty && len(bodyBytes) > 0 {
		var out bytes.Buffer
		if json.Indent(&out, bodyBytes, "", "  ") == nil {
			fmt.Println()
			fmt.Println(out.String())
			return
		}
	}
	if len(bodyBytes) > 0 {
		fmt.Println()
		fmt.Print(string(bodyBytes))
	} else {
		fmt.Println()
	}
}
